package cli

// The binary does matching so Bash and Zsh also support fuzzy workspace/task
// names and case-insensitive syntax without changing opaque candidate values.
var completionScripts = map[string]string{
	"bash": `# Generated by wtf completion bash. Also supports the common f alias.
_wtf_completion_theme() {
    [[ $- == *i* ]] || return 0
    if [[ -n "${NO_COLOR:-}" || "${TERM:-}" == dumb ]]; then
        bind 'set colored-completion-prefix off'
        return 0
    fi
    # Readline uses its native terminal-palette highlight, or the user's
    # LS_COLORS prefix style. Do not bake RGB colors into command candidates.
    # Readline's abbreviated '...' prefix display takes precedence over color.
    bind 'set completion-prefix-display-length 0'
    bind 'set colored-completion-prefix on'
}
_wtf_completion_theme
_wtf_complete() {
    _wtf_completion_theme
    local binary="${WTF_BINARY:-wtf}" line directive=4 word previous="" i
    local -a words=()
    # Bash splits '=' into a separate completion word by default. Reassemble
    # flag assignments before querying the binary, without evaluating argv.
    for ((i=1; i<=COMP_CWORD; i++)); do
        word="${COMP_WORDS[i]}"
        if [[ "$word" == = && ${#words[@]} -gt 0 ]]; then
            words[${#words[@]}-1]+="="
        elif [[ "$previous" == = && ${#words[@]} -gt 0 ]]; then
            words[${#words[@]}-1]+="$word"
        else
            words+=("$word")
        fi
        previous="$word"
    done
    COMPREPLY=()
    while IFS= read -r line; do
        if [[ "$line" == :* ]]; then
            directive="${line#:}"
        else
            line="${line%%$'\t'*}"
            if [[ "${words[${#words[@]}-1]}" == *=* && "${COMP_WORDS[COMP_CWORD]}" != *=* ]]; then
                line="${line#*=}"
            fi
            COMPREPLY+=("$line")
        fi
    done < <("$binary" __complete "${words[@]}" 2>/dev/null)
    if [[ "$directive" == 0 ]]; then
        while IFS= read -r line; do COMPREPLY+=("$line"); done < <(compgen -f -- "${COMP_WORDS[COMP_CWORD]}")
        compopt -o filenames 2>/dev/null
    fi
}
complete -F _wtf_complete wtf f
`,
	"zsh": `# Generated by wtf completion zsh. Also supports the common f alias.
_wtf_complete() {
    local binary="${WTF_BINARY:-wtf}" line directive=4
    local -a candidates descriptions
    while IFS= read -r line; do
        if [[ "$line" == :* ]]; then
            directive="${line#:}"
        else
            candidates+=("${line%%$'\t'*}")
            descriptions+=("${line#*$'\t'}")
        fi
    done < <("$binary" __complete "${words[@]:1:$((CURRENT-1))}" 2>/dev/null)
    (( ${#candidates} )) && compadd -U -d descriptions -- "${candidates[@]}"
    [[ "$directive" == 0 ]] && _files
    return 0
}
compdef _wtf_complete wtf f
`,
	"fish": `# Generated by wtf completion fish. Also supports the common f alias.
function __wtf_complete
    set -l binary wtf
    if set -q WTF_BINARY; set binary $WTF_BINARY; end
    set -l words (commandline -opc)
    set -l current (commandline -ct)
    for line in ($binary __complete $words[2..-1] "$current" 2>/dev/null)
        if test "$line" = :0
            __fish_complete_path "$current"
        else if not string match -q ':*' -- "$line"
            printf '%s\n' "$line"
        end
    end
end
complete -c wtf -f -a '(__wtf_complete)'
complete -c f -f -a '(__wtf_complete)'
`,
}
